-- ══════════════════════════════════════
-- Darwoft Take-Home Challenge — DB Fiddle
-- MySQL 9
-- ══════════════════════════════════════

CREATE TABLE users (
    user_id      INT PRIMARY KEY,
    signup_date  DATE,
    country      VARCHAR(10),
    plan_type    VARCHAR(20)
);

CREATE TABLE accounts (
    account_id   INT PRIMARY KEY,
    user_id      INT,
    account_type VARCHAR(20),
    created_at   DATETIME
);

CREATE TABLE transactions (
    transaction_id   INT PRIMARY KEY,
    account_id       INT,
    amount           DECIMAL(10,2),
    currency         VARCHAR(10),
    transaction_type VARCHAR(20),
    status           VARCHAR(20),
    created_at       DATETIME
);

